(window.LADDER_CARDS=window.LADDER_CARDS||{})["44a"]=[{"q": "If 1 = 0 in a ring, how many members has it?", "a": "one", "w": ["two", "none", "endlessly many"], "why": "The one-member technique: w = w · 1 = w · 0 = 0."}, {"q": "Which is a field?", "a": "ℤ/7", "w": ["ℤ/6", "ℤ", "ℤ[x]"], "why": "Every member but 0 of ℤ/7 has a reciprocal."}, {"q": "On ℤ/6, 2 · 1 = 2 · 4 with 1 ≠ 4. What breaks cancelling?", "a": "the zero product 2 · 3 = 0", "w": ["2 has a reciprocal", "6 is even", "ℤ/6 does not turn about"], "why": "The cancel-exactly-when technique: cancelling fails exactly when there are zero products."}, {"q": "Which are the undoable members of ℤ/6?", "a": "1 and 5", "w": ["1 only", "1, 2, 3, 4, 5", "1, 3, 5"], "why": "5 · 5 = 25 = 1; 2, 3, 4 make 0 with something."}, {"q": "A cancelling ring with finitely many members is…", "a": "a field", "w": ["ℤ/n for some n", "a ring of grids", "never a field"], "why": "The finite-cancelling technique: w ↦ aw is one-to-one, so onto, so 1 is hit."}, {"q": "In the ring of parts of a set, what is X · X?", "a": "X", "w": ["∅", "the whole set", "X twice"], "why": "Times is ∩, and X ∩ X = X."}, {"q": "How many answers has x² = 1 on ℤ/8?", "a": "four: 1, 3, 5, 7", "w": ["two: 1 and 7", "one", "eight"], "why": "ℤ/8 has zero products, so (x − 1)(x + 1) = 0 does not force a factor to be 0."}, {"q": "Why does (w + b)² = w² + 2wb + b² fail for grids?", "a": "grids do not turn about: wb ≠ bw", "w": ["grids have no 2", "grids have no squares", "grids are not a ring"], "why": "(w + b)² = w² + wb + bw + b²."}, {"q": "The four-part numbers with i² = j² = k² = ijk = −1 have a reciprocal for every member but 0. What do they miss of a field?", "a": "turning about", "w": ["cancelling", "a 1", "negatives"], "why": "ij = k but ji = −k."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["44b"]=[{"q": "An ideal of ℚ holds 2. What else must it hold?", "a": "everything", "w": ["only the even numbers", "only the multiples of 2 in ℤ", "only 0 and 2"], "why": "Undoable-fills: 2 is undoable in ℚ."}, {"q": "How many ideals has a field?", "a": "two", "w": ["one", "endlessly many", "none"], "why": "{0} and the field itself."}, {"q": "ℝ[x]/(x² + 1) is a copy of…", "a": "ℂ", "w": ["ℝ", "ℝ × ℝ", "ℤ/2"], "why": "The lost-ideal technique with p ↦ p(i)."}, {"q": "R/M is a field exactly when M is…", "a": "largest", "w": ["prime", "{0}", "made by one member"], "why": "The largest-ideal technique."}, {"q": "Why is 6ℤ not prime?", "a": "2 · 3 ∈ 6ℤ with neither in it", "w": ["6 is even", "6ℤ is not an ideal", "6ℤ is largest"], "why": "ℤ/6 has a zero product."}, {"q": "At which point does the honest-product technique need I to swallow multiplying?", "a": "w(b − b′) and (w − w′)b′ are in I", "w": ["w + b is in I", "1 is in I", "I has an inverse"], "why": "Both are a member of I times a member of R."}, {"q": "Which ideals of ℤ/12 are largest?", "a": "(2) and (3)", "w": ["(4) and (6)", "(0)", "(1)"], "why": "Their quotients ℤ/2 and ℤ/3 are fields."}, {"q": "ℝ[x]/(x²) has a member other than 0 whose square is…", "a": "0", "w": ["1", "−1", "x"], "why": "x · x = x² = 0 there."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["44c"]=[{"q": "On ℤ/4, what is (2x + 1)²?", "a": "1", "w": ["4x² + 4x + 1, of degree 2", "2x + 1", "0"], "why": "4 = 0 on ℤ/4: the top coefficient 2 · 2 vanishes."}, {"q": "Over a field, division by d ≠ 0 gives p = dq + r with…", "a": "r = 0 or deg r < deg d", "w": ["deg r = deg d", "r a constant always", "q = 0"], "why": "The top-undoable technique."}, {"q": "The remainder of p on division by x − 3 is…", "a": "p(3)", "w": ["p(−3)", "0", "the top coefficient"], "why": "Remainder-is-value."}, {"q": "Every ideal of F[x] other than {0} is…", "a": "the multiples of one polynomial", "w": ["finite", "the whole ring", "made by two polynomials"], "why": "The one-maker technique: any member of least degree."}, {"q": "Why is (2, x) in ℤ[x] made by no single member?", "a": "a maker would divide 2 and x, so be ±1 or ±2, and neither works", "w": ["ℤ[x] has no ideals", "2 and x are partners", "x has no degree"], "why": "Members of (2, x) have even constant term, and 2 ∤ x."}, {"q": "How many zeros has x⁴ + 1 on ℤ/17?", "a": "four: 2, 8, 9, 15", "w": ["none", "two", "one"], "why": "2⁴ = 16 = −1 on the clock of 17."}, {"q": "Is x² + x the zero polynomial on ℤ/2?", "a": "no, though both its values are 0", "w": ["yes", "only at 0", "it has no values"], "why": "Coefficients, not values, make a polynomial."}, {"q": "Which clocks have exactly two members whose square is 1?", "a": "4, pᵏ and 2pᵏ, p an odd prime", "w": ["every clock", "only primes", "only even clocks"], "why": "On the clock of 8 there are four."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["44d"]=[{"q": "In a principal ring, every unsplittable member is…", "a": "prime", "w": ["undoable", "0", "a square"], "why": "The unsplittable-is-prime technique, by a largest ideal."}, {"q": "Which polynomial does the prime 3 show cannot be split over ℚ?", "a": "x⁵ − 6x + 3", "w": ["x² − 9", "x³ + 3x + 9", "x⁴ − 10x² + 1"], "why": "3 divides −6 and 3, not 1, and 9 ∤ 3."}, {"q": "The content of a product of whole-number polynomials is…", "a": "the product of their contents", "w": ["the sum of their contents", "always 1", "their greatest common divisor"], "why": "The content-multiplies technique."}, {"q": "Why is 2x + 2 unsplittable in ℚ[x]?", "a": "2 is undoable in ℚ", "w": ["it has degree 1 and no factor", "x + 1 is prime", "2 is prime"], "why": "In ℤ[x], 2 · (x + 1) is a split."}, {"q": "No prime fits a polynomial in the prime-wedge test. What follows?", "a": "nothing", "w": ["it splits", "it cannot be split", "it has a whole zero"], "why": "The test only ever says no."}, {"q": "Must a ring with one factoring be principal?", "a": "no: ℤ[x] has one factoring and (2, x)", "w": ["yes", "only if finite", "only for fields"], "why": "42d.6.3."}, {"q": "Which prime shows x⁴ + x³ + x² + x + 1 cannot be split, after putting x + 1 for x?", "a": "5", "w": ["2", "3", "none"], "why": "The coefficients become 1, 5, 10, 10, 5."}, {"q": "Why does a chain (w₀) ⊊ (w₁) ⊊ ⋯ stop in a principal ring?", "a": "its union is an ideal made by one member, which lies in some (wₙ)", "w": ["ideals are finite", "sizes fall", "every member is undoable"], "why": "The one-factoring technique’s first half."}];
