(window.LADDER_CARDS=window.LADDER_CARDS||{})["44g"]=[{"q": "Why can no field have 6 members?", "a": "its size is a power of its bottom prime", "w": ["6 is even", "ℤ/6 has zero products", "6 is not prime"], "why": "The prime-power-size technique."}, {"q": "The field of four is…", "a": "(ℤ/2)[x]/(x² + x + 1)", "w": ["ℤ/4", "ℤ/2 × ℤ/2 with times by places", "ℤ[i]/(4)"], "why": "The unsplittable-builds technique."}, {"q": "In a ring with p · 1 = 0, (w + b)ᵖ is…", "a": "wᵖ + bᵖ", "w": ["wᵖ + pwb + bᵖ", "(wb)ᵖ", "0"], "why": "Power-keeps-plus: C(p, k) is a multiple of p for 0 < k < p."}, {"q": "Members other than 0 of every finite field are…", "a": "the powers of one of them", "w": ["all of order 2", "squares", "their own reciprocals"], "why": "The whole-hand technique."}, {"q": "Order of 1 + i in the field of 9?", "a": "8", "w": ["4", "2", "3"], "why": "(1 + i)⁴ = 2 ≠ 1, (1 + i)⁸ = 1."}, {"q": "Is x⁴ + x² + 1 unsplittable on ℤ/2?", "a": "no: it is (x² + x + 1)²", "w": ["yes, it has no zero", "yes, by degree", "it is x⁴ + 1"], "why": "No zero rules out only factors of degree 1."}, {"q": "Does the field of 8 hold the field of 4?", "a": "no", "w": ["yes", "only as a set", "only if 8 is prime"], "why": "2 does not divide 3."}, {"q": "Can a finite field be ordered?", "a": "no: p · 1 = 0", "w": ["yes", "only ℤ/2", "only with √−1"], "why": "In an order 1 + ⋯ + 1 > 0."}];
